import { test, expect } from '@playwright/test';

test.describe('Async Error Retry Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <div id="app">
        <button id="trigger-async-error">Trigger Async Operation</button>
        <div id="error-container" style="display:none;">
          <p id="error-message"></p>
          <button id="retry-button">Retry</button>
        </div>
        <div id="success-container" style="display:none;">
          <p id="success-message">Operation completed successfully</p>
        </div>
        <div id="loading-indicator" style="display:none;">Loading...</div>
      </div>
      <script>
        let attemptCount = 0;
        const maxAttempts = 3;

        async function performAsyncOperation() {
          const loadingIndicator = document.getElementById('loading-indicator');
          const errorContainer = document.getElementById('error-container');
          const successContainer = document.getElementById('success-container');
          const errorMessage = document.getElementById('error-message');

          loadingIndicator.style.display = 'block';
          errorContainer.style.display = 'none';
          successContainer.style.display = 'none';

          attemptCount++;

          try {
            await new Promise((resolve, reject) => {
              setTimeout(() => {
                if (attemptCount < 2) {
                  reject(new Error('Async operation failed: Network timeout'));
                } else {
                  resolve('Success');
                }
              }, 500);
            });

            loadingIndicator.style.display = 'none';
            successContainer.style.display = 'block';
          } catch (error) {
            loadingIndicator.style.display = 'none';
            errorContainer.style.display = 'block';
            errorMessage.textContent = error.message;
          }
        }

        document.getElementById('trigger-async-error').addEventListener('click', performAsyncOperation);
        document.getElementById('retry-button').addEventListener('click', performAsyncOperation);
      </script>
    `);
  });

  test('should display error message when async operation fails', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Trigger Async Operation' });
    await triggerButton.click();

    const errorContainer = page.locator('#error-container');
    await expect(errorContainer).toBeVisible({ timeout: 2000 });

    const errorMessage = page.locator('#error-message');
    await expect(errorMessage).toContainText('Async operation failed: Network timeout');
  });

  test('should display retry button when async error occurs', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Trigger Async Operation' });
    await triggerButton.click();

    const errorContainer = page.locator('#error-container');
    await expect(errorContainer).toBeVisible({ timeout: 2000 });

    const retryButton = page.getByRole('button', { name: 'Retry' });
    await expect(retryButton).toBeVisible();
  });

  test('should successfully retry async operation after initial failure', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Trigger Async Operation' });
    await triggerButton.click();

    const errorContainer = page.locator('#error-container');
    await expect(errorContainer).toBeVisible({ timeout: 2000 });

    const retryButton = page.getByRole('button', { name: 'Retry' });
    await retryButton.click();

    const successContainer = page.locator('#success-container');
    await expect(successContainer).toBeVisible({ timeout: 2000 });

    const successMessage = page.locator('#success-message');
    await expect(successMessage).toContainText('Operation completed successfully');
  });

  test('should hide error container and show loading state during retry', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Trigger Async Operation' });
    await triggerButton.click();

    const errorContainer = page.locator('#error-container');
    await expect(errorContainer).toBeVisible({ timeout: 2000 });

    const retryButton = page.getByRole('button', { name: 'Retry' });
    await retryButton.click();

    const loadingIndicator = page.locator('#loading-indicator');
    await expect(loadingIndicator).toBeVisible();

    await expect(errorContainer).not.toBeVisible();
  });

  test('should allow multiple retry attempts', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Trigger Async Operation' });
    await triggerButton.click();

    const errorContainer = page.locator('#error-container');
    await expect(errorContainer).toBeVisible({ timeout: 2000 });

    const retryButton = page.getByRole('button', { name: 'Retry' });

    // First retry attempt
    await retryButton.click();
    const successContainer = page.locator('#success-container');
    await expect(successContainer).toBeVisible({ timeout: 2000 });

    const successMessage = page.locator('#success-message');
    await expect(successMessage).toContainText('Operation completed successfully');
  });
});
